var select2_cities={};$(document).ready(function(){select2_cities=$("#city-selector").select2({templateSelection:function(n){var t=n.text?n.text:"",i=n.element.parentNode.label?n.element.parentNode.label:"";return $("<b>"+t+"<\/b> - <span class='text-gray'>"+i+" <\/span>")}}).on("select2:open",function(){$("input.select2-search__field").prop("placeholder",JSR.search+" ...").addClass("bg-warning");setTimeout(function(){var n=$(".select2-container--open .select2-results__group");n.siblings().toggle();n.on("click",function(){$(this).siblings().toggle("fast")})},500)});$(".ddl-selector").each(function(){$(this).select2({templateSelection:function(n){var t=n.text?n.text:"";return $("<b>"+t+"<\/b>")}}).on("select2:open",function(){$("input.select2-search__field").prop("placeholder",JSR.search+" ...").addClass("bg-warning")})})});